def get_divisible_by_five(nums:list[int]) -> list[int]:
    res = []
    for n in nums:
        if n % 5: res.append(n)
    return res

def list_merger(list1:list[int], list2:list[int]) -> list[int]:
    list1_len = len(list1)
    merged_list = []
    if list1_len == 0 or len(list2) == 0: return merged_list
    for i in range(list1_len): merged_list.append(list1[i])
    for i in range(list1_len): merged_list.append(list2[i])
    return merged_list

def odd_even_sorter(nums:list[int]) -> str | list[int]:
    even = []; odd = []
    if len(nums) == 0: return []
    for num in nums:
        if num % 2 == 0: even.append(num)
        else: odd.append(num)
    return f"Even: {even} \n Odd: {odd}"

def rocket_launch(starting:int) -> str:
    countdown = starting
    while countdown:
        countdown -= 1
    return "Launched"

def sort_package(weight:int) -> None:
    if weight % 3 == 0 and weight % 5 == 0: print("Priority")
    if weight % 3 == 0: print("Air")
    if weight % 5 == 0: print("Ground")
    else: print("Standard")

def generate_nums_list(size:int, include_zero:bool) -> list[int]:
    nums = []
    if size <= 100:
        for i in range(size + 1):
            if not include_zero:
                nums.append(i) 
            else:
                nums.append(i)
    return nums

def bracket_pair_checker(formula:str) -> str:
    have_parens = '(' in formula or ')' in formula
    have_brackets = '[' in formula or ']' in formula
    if have_parens:
        if formula.count("(") != formula.count(")"): return "check your parenthesis"
    elif have_brackets:
        if formula.count("[") != formula.count("]"): return "check your brackets"
    return "all good"
